import{CONFIG}from"./config.js";import{supabase}from"./supabase-client.js";
const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
const app=$("#app"),modal=$("#modalDialog"),auth=$("#authDialog");
const S={user:null,profile:null,wallet:{balance:0},products:[],categories:[],notes:[],slides:[],settings:{},authMode:"login",adminGroup:"dashboard",adminPage:"overview",page:1,query:"",filter:"",deferredInstall:null};
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
const money=n=>`${Number(n||0).toFixed(2)} ${CONFIG.CURRENCY}`,dt=v=>new Date(v).toLocaleString("ar");
const debounce=(fn,ms=250)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}};
function toast(m,t="success"){const e=document.createElement("div");e.className=`toast ${t}`;e.textContent=m;$("#toastRoot").append(e);setTimeout(()=>e.remove(),3200)}
function badge(s){const m={pending:["قيد المراجعة","warning"],approved:["مقبول","success"],rejected:["مرفوض","danger"],paid:["مدفوع","success"],processing:["قيد التنفيذ","warning"],delivered:["تم التسليم","success"],cancelled:["ملغي","danger"],refunded:["مسترد","warning"],active:["نشط","success"],blocked:["محظور","danger"],available:["متاح","success"],paused:["موقوف","warning"],sold_out:["نفد","danger"]};const[t,c]=m[s]||[s||"-",""];return`<span class="badge ${c}">${t}</span>`}
function section(t,p,a=""){return`<div class="section"><div><h2>${t}</h2><p>${p}</p></div>${a}</div>`}
function empty(t,p="لا توجد بيانات"){return`<div class="card empty"><h2>${t}</h2><p>${p}</p></div>`}
function openModal(h){modal.innerHTML=`<div class="dialog-body"><div class="grip"></div>${h}</div>`;modal.showModal();document.body.style.overflow="hidden";$$("[data-close]",modal).forEach(b=>b.onclick=closeModal)}
function closeModal(){modal.close();document.body.style.overflow=""}
function needUser(){if(!S.user){auth.showModal();toast("سجل الدخول أولًا","error");return false}return true}
function needAdmin(){if(S.profile?.role!=="admin"){app.innerHTML=empty("غير مصرح");return false}return true}
function pager(page,total,size){const pages=Math.max(1,Math.ceil(total/size)),start=Math.max(1,page-2),end=Math.min(pages,page+2);return`<div class="pagination"><button class="page-btn" data-page="${Math.max(1,page-1)}">‹</button>${Array.from({length:end-start+1},(_,i)=>start+i).map(n=>`<button class="page-btn ${n===page?"active":""}" data-page="${n}">${n}</button>`).join("")}<button class="page-btn" data-page="${Math.min(pages,page+1)}">›</button></div>`}
function bindPager(render){$$("[data-page]").forEach(b=>b.onclick=()=>{S.page=+b.dataset.page;render()})}
function adminHeader(title,sub,actions=""){return`${section(title,sub,actions)}<div class="admin-toolbar"><input id="adminSearch" class="input" placeholder="بحث..." value="${esc(S.query)}"><select id="adminFilter" class="input"><option value="">الكل</option></select><button id="clearFilters" class="btn soft">مسح</button></div>`}
async function init(){bind();setTheme(localStorage.theme||"dark");const{data}=await supabase.auth.getSession();S.user=data.session?.user||null;await loadIdentity();await loadPublic();await loadNotes();updateHeader();subscribeRealtime();supabase.auth.onAuthStateChange(async(_,s)=>{S.user=s?.user||null;await loadIdentity();await loadNotes();updateHeader();route()});setTimeout(()=>$("#splash").classList.add("hide"),500);route();if("serviceWorker"in navigator)navigator.serviceWorker.register("./service-worker.js").catch(()=>{})}
function bind(){$("#themeButton").onclick=()=>setTheme(document.documentElement.dataset.theme==="dark"?"light":"dark");$("#notificationButton").onclick=showNotes;$("#authForm").onsubmit=submitAuth;$("#switchAuth").onclick=()=>{S.authMode=S.authMode==="login"?"register":"login";renderAuthMode()};$$("[data-close-dialog]").forEach(b=>b.onclick=()=>document.getElementById(b.dataset.closeDialog).close());window.addEventListener("hashchange",route);window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();S.deferredInstall=e;$("#installButton").classList.remove("hidden")});$("#installButton").onclick=async()=>{if(!S.deferredInstall)return toast("استخدم خيار تثبيت التطبيق من قائمة Chrome","error");S.deferredInstall.prompt();await S.deferredInstall.userChoice;S.deferredInstall=null;$("#installButton").classList.add("hidden")}}
function setTheme(t){document.documentElement.dataset.theme=t;localStorage.theme=t;$("#themeButton").textContent=t==="dark"?"☀":"☾"}
function renderAuthMode(){const r=S.authMode==="register";$("#registerFields").classList.toggle("hidden",!r);$("#authTitle").textContent=r?"إنشاء حساب":"تسجيل الدخول";$("#authSubmit").textContent=r?"إنشاء الحساب":"دخول";$("#switchAuth").textContent=r?"لديك حساب؟ سجل الدخول":"ليس لديك حساب؟ أنشئ حسابًا"}
async function submitAuth(e){e.preventDefault();try{const email=$("#email").value.trim(),password=$("#password").value;if(S.authMode==="register"){const{error}=await supabase.auth.signUp({email,password,options:{data:{full_name:$("#fullName").value.trim(),phone:$("#phone").value.trim()}}});if(error)throw error}else{const{error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error}auth.close();toast("تمت العملية بنجاح")}catch(e){toast(e.message,"error")}}
async function loadIdentity(){S.profile=null;S.wallet={balance:0};if(!S.user)return;const[{data:p},{data:w}]=await Promise.all([supabase.from("profiles").select("*").eq("id",S.user.id).maybeSingle(),supabase.from("wallets").select("balance").eq("user_id",S.user.id).maybeSingle()]);S.profile=p;S.wallet=w||{balance:0}}
async function loadPublic(){const[{data:s},{data:a},{data:st}]=await Promise.all([supabase.from("store_slides").select("*").eq("is_active",true).order("sort_order"),supabase.from("announcements").select("*").eq("is_active",true).eq("kind","bar").order("created_at",{ascending:false}).limit(1),supabase.from("store_settings").select("*").limit(1).maybeSingle()]);S.slides=s||[];S.settings=st||{};$("#storeName").textContent=S.settings.store_name||"علي شوب";const bar=$("#announcementBar");if(a?.[0]){bar.innerHTML=`${esc(a[0].message)}<button>×</button>`;bar.classList.remove("hidden");bar.querySelector("button").onclick=()=>bar.classList.add("hidden")}else bar.classList.add("hidden")}
async function loadNotes(){S.notes=[];if(!S.user)return;const{data}=await supabase.from("notifications").select("*").order("created_at",{ascending:false}).limit(50);S.notes=data||[]}
function updateHeader(){$("#notificationButton").classList.toggle("hidden",!S.user);const n=S.notes.filter(x=>!x.is_read).length;$("#notificationCount").textContent=n;$("#notificationCount").classList.toggle("hidden",!n)}
function subscribeRealtime(){if(!S.user)return;supabase.channel(`notes-${S.user.id}`).on("postgres_changes",{event:"INSERT",schema:"public",table:"notifications"},async p=>{if(p.new.user_id===S.user.id||p.new.user_id===null){toast(p.new.title);await loadNotes();updateHeader()}}).subscribe()}
async function showNotes(){if(!needUser())return;openModal(`<div class="sheet-head"><div><h2>الإشعارات</h2><p>آخر تحديثات حسابك</p></div><button data-close>×</button></div><div class="list">${S.notes.length?S.notes.map(n=>`<div class="card item"><div class="item-main"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${dt(n.created_at)}</small></div>${n.is_read?"":badge("pending")}</div>`).join(""):empty("لا توجد إشعارات")}</div>`);const ids=S.notes.filter(n=>!n.is_read&&n.user_id===S.user.id).map(n=>n.id);if(ids.length){await supabase.from("notifications").update({is_read:true}).in("id",ids);await loadNotes();updateHeader()}}
function route(){const r=location.hash.replace("#/","").split("?")[0]||"home";$$("[data-route]").forEach(a=>a.classList.toggle("active",a.dataset.route===r));$("#pageTitle").textContent={home:"المنتجات الرقمية",products:"جميع المنتجات",orders:"طلباتي",wallet:"المحفظة",account:"حسابي",admin:"لوحة الإدارة"}[r]||"علي شوب";({home,products,orders,wallet,account,admin}[r]||home)()}
async function catalog(){const[{data:p},{data:c}]=await Promise.all([supabase.from("products_with_stock").select("*").eq("is_active",true).order("created_at",{ascending:false}),supabase.from("categories").select("*").eq("is_active",true).order("sort_order")]);S.products=p||[];S.categories=c||[]}
function pcard(p){const sold=p.availability_status==="sold_out";return`<article class="card product ${sold?"soldout":""}">${sold?'<div class="soldout-ribbon">نفد المخزون</div>':""}<button class="favorite-btn" data-favorite="${p.id}">♡</button><div class="product-image">${p.image_url?`<img src="${esc(p.image_url)}">`:"🛍️"}</div><div class="product-body"><span class="badge">${esc(p.category_name||"منتج رقمي")}</span><h3>${esc(p.name)}</h3><p>${esc(p.description||"منتج رقمي")}</p><div class="product-foot"><span class="price">${money(p.price)}</span><button class="small" data-product="${p.id}">${sold?"غير متوفر":"عرض"}</button></div></div></article>`}
function bindProducts(){$$("[data-product]").forEach(b=>b.onclick=()=>details(b.dataset.product));$$("[data-favorite]").forEach(b=>b.onclick=()=>toggleFavorite(b.dataset.favorite))}
async function toggleFavorite(id){if(!needUser())return;const{data}=await supabase.from("favorites").select("id").eq("user_id",S.user.id).eq("product_id",id).maybeSingle();if(data){await supabase.from("favorites").delete().eq("id",data.id);toast("تمت الإزالة من المفضلة")}else{const{error}=await supabase.from("favorites").insert({user_id:S.user.id,product_id:id});if(error)return toast(error.message,"error");toast("تمت الإضافة إلى المفضلة")}}
async function home(){await catalog();const slides=S.slides.length?S.slides:[{title:"كل ما تحتاجه رقميًا",subtitle:"اشحن محفظتك واشترِ بسهولة",button_text:"تصفح المنتجات",button_url:"#/products"}];app.innerHTML=`<div class="hero-slider">${slides.map((s,i)=>`<section class="slide ${i===0?"active":""}" style="${s.image_url?`background-image:linear-gradient(90deg,rgba(23,19,55,.72),rgba(23,19,55,.25)),url('${esc(s.image_url)}')`:""}"><div class="slide-overlay"><span class="badge">علي شوب</span><h1>${esc(s.title)}</h1><p>${esc(s.subtitle||"")}</p><a class="btn primary" href="${esc(s.button_url||"#/products")}">${esc(s.button_text||"استكشف")}</a></div></section>`).join("")}<div class="dots">${slides.map((_,i)=>`<button class="dot ${i===0?"active":""}" data-slide="${i}"></button>`).join("")}</div></div><div class="wallet-strip"><div><small>رصيد محفظتك</small><strong>${money(S.wallet.balance)}</strong></div><a href="#/wallet" class="btn soft">شحن</a></div>${section("منتجات مميزة","أحدث المنتجات المتاحة")}<div class="grid">${S.products.slice(0,6).map(pcard).join("")||empty("لا توجد منتجات")}</div>`;let cur=0,els=$$(".slide"),dots=$$(".dot");const go=i=>{els[cur].classList.remove("active");dots[cur].classList.remove("active");cur=i;els[cur].classList.add("active");dots[cur].classList.add("active")};dots.forEach(d=>d.onclick=()=>go(+d.dataset.slide));if(els.length>1)setInterval(()=>go((cur+1)%els.length),5000);bindProducts()}
async function products(){await catalog();app.innerHTML=`${section("المنتجات","ابحث واختر المنتج المناسب")}<div class="search-row"><input id="search" class="input" placeholder="بحث..."><select id="cat" class="input"><option value="">الكل</option>${S.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select></div><div id="pgrid" class="grid" style="margin-top:15px">${S.products.map(pcard).join("")}</div>`;const f=()=>{const q=$("#search").value.toLowerCase(),c=$("#cat").value,l=S.products.filter(p=>(!c||p.category_id===c)&&(`${p.name} ${p.description||""}`).toLowerCase().includes(q));$("#pgrid").innerHTML=l.map(pcard).join("")||empty("لا توجد نتائج");bindProducts()};$("#search").oninput=f;$("#cat").onchange=f;bindProducts()}
function details(id){const p=S.products.find(x=>String(x.id)===String(id)),sold=p.availability_status==="sold_out";openModal(`<div class="sheet-head"><div><h2>${esc(p.name)}</h2><p>${sold?"نفد المخزون":"متوفر الآن"}</p></div><button data-close>×</button></div><div class="product-image" style="height:230px;border-radius:19px">${p.image_url?`<img src="${esc(p.image_url)}">`:"🛍️"}</div><p style="line-height:1.9;color:var(--m)">${esc(p.description||"")}</p><label>كوبون الخصم<input id="couponCode" placeholder="اختياري"></label><div class="product-foot"><span class="price">${money(p.price)}</span><button id="buy" class="btn ${sold?"soft":"primary"}" ${sold?"disabled":""}>${sold?"غير متوفر حاليًا":"شراء الآن"}</button></div>`);if(!sold)$("#buy").onclick=()=>buy(p)}
async function buy(p){if(!needUser()||!confirm(`شراء ${p.name}؟`))return;const code=$("#couponCode")?.value.trim()||null;const{error}=await supabase.rpc("purchase_product_v4",{p_product_id:p.id,p_idempotency_key:crypto.randomUUID(),p_coupon_code:code});if(error)return toast(error.message,"error");toast("تم الشراء");closeModal();await loadIdentity();location.hash="#/orders"}
async function orders(){if(!needUser())return app.innerHTML=empty("طلباتي","سجل الدخول");const{data}=await supabase.from("orders").select("*,product:products(name)").order("created_at",{ascending:false}),r=data||[];app.innerHTML=`${section("طلباتي","الشراء والتسليم والاسترداد")}<div class="list">${r.map(o=>`<div class="card item"><div class="item-main"><h3>${esc(o.product?.name||"-")}</h3><p>${esc(o.order_number)} • ${money(o.total)}</p></div><div class="item-actions">${badge(o.status)}<button class="small" data-order="${o.id}">تفاصيل</button></div></div>`).join("")||empty("لا توجد طلبات")}</div>`;$$("[data-order]").forEach(b=>b.onclick=()=>{const o=r.find(x=>x.id===b.dataset.order);openModal(`<div class="sheet-head"><h2>${esc(o.order_number)}</h2><button data-close>×</button></div><p>${badge(o.status)}</p><div class="note">${esc(o.delivery_data||"لم يتم التسليم بعد")}</div>${["processing","paid"].includes(o.status)?`<button id="requestCancel" class="btn danger block" style="margin-top:12px">طلب إلغاء</button>`:""}`);if($("#requestCancel"))$("#requestCancel").onclick=async()=>{const reason=prompt("سبب الإلغاء:");if(!reason)return;const{error}=await supabase.rpc("request_order_cancel",{p_order_id:o.id,p_reason:reason});if(error)return toast(error.message,"error");toast("تم إرسال طلب الإلغاء");closeModal();orders()}})}
async function wallet(){if(!needUser())return app.innerHTML=empty("المحفظة","سجل الدخول");const[{data:t},{data:d}]=await Promise.all([supabase.from("wallet_transactions").select("*").order("created_at",{ascending:false}).limit(50),supabase.from("deposit_requests").select("*,payment_method:payment_methods(name)").order("created_at",{ascending:false})]);app.innerHTML=`${section("المحفظة","الرصيد وطرق الشحن",`<button id="deposit" class="btn primary">طلب شحن</button>`)}<div class="stats"><div class="card stat"><small>الرصيد</small><strong>${money(S.wallet.balance)}</strong></div><div class="card stat"><small>طلبات الشحن</small><strong>${(d||[]).length}</strong></div></div><div class="card item" style="margin-top:12px"><div class="item-main"><h3>استخدام بطاقة شحن</h3><p>أدخل رمز البطاقة لإضافة الرصيد فورًا</p></div><button id="redeemCard" class="btn soft">استخدام</button></div>${section("الحركات المالية","آخر العمليات")}<div class="list">${(t||[]).map(x=>`<div class="card item"><div class="item-main"><h3>${esc(x.description||x.type)}</h3><p>${dt(x.created_at)}</p></div><strong>${money(x.amount)}</strong></div>`).join("")||empty("لا توجد حركات")}</div>`;$("#deposit").onclick=depositForm;$("#redeemCard").onclick=async()=>{const code=prompt("أدخل رمز بطاقة الشحن:");if(!code)return;const{data,error}=await supabase.rpc("redeem_recharge_card",{p_code:code.trim()});if(error)return toast(error.message,"error");toast(data.message||"تم شحن الرصيد");await loadIdentity();wallet()}}
async function depositForm(){const{data}=await supabase.from("payment_methods").select("*").eq("is_active",true).order("sort_order"),m=data||[];if(!m.length)return toast("لا توجد طرق دفع","error");openModal(`<div class="sheet-head"><h2>طلب شحن</h2><button data-close>×</button></div><form id="df"><label>طريقة الدفع<select id="method">${m.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></label><label>المبلغ<input id="amount" type="number" min="1" required></label><label>رقم التحويل<input id="ref" required></label><label>رابط الإثبات<input id="receipt" type="url"></label><button class="btn primary block">إرسال</button></form>`);$("#df").onsubmit=async e=>{e.preventDefault();const{error}=await supabase.from("deposit_requests").insert({user_id:S.user.id,payment_method_id:$("#method").value,amount:+$("#amount").value,transfer_reference:$("#ref").value,receipt_url:$("#receipt").value||null});if(error)return toast(error.message,"error");toast("تم إرسال الطلب");closeModal();wallet()}}
function account(){if(!S.user){app.innerHTML=`${section("حسابي","سجل الدخول")}<div class="card empty"><h2>أهلًا بك</h2><button id="openAuth" class="btn primary">تسجيل الدخول</button></div>`;$("#openAuth").onclick=()=>auth.showModal();return}app.innerHTML=`${section("حسابي","المعلومات والإعدادات")}<div class="card item"><div class="item-main"><h3>${esc(S.profile?.full_name||"مستخدم")}</h3><p>${esc(S.user.email)}</p></div>${badge(S.profile?.status)}</div>${S.profile?.role==="admin"?`<a href="#/admin" class="card item" style="margin-top:11px"><div class="item-main"><h3>لوحة الإدارة</h3><p>إدارة المتجر بالكامل</p></div><span>›</span></a>`:""}<button id="logout" class="card item" style="width:100%;margin-top:11px;color:var(--bad)"><h3>تسجيل الخروج</h3></button>`;$("#logout").onclick=()=>supabase.auth.signOut()}

/* ---------- ADMIN ---------- */
async function admin(){if(!needAdmin())return;if(S.adminGroup==="dashboard"){app.innerHTML=`${section("لوحة الإدارة","اختر القسم المطلوب")}<div class="admin-groups">${[["sales","المبيعات","الطلبات والإلغاء والاسترداد"],["catalog","الكتالوج","المنتجات والتصنيفات والمخزون"],["finance","الأموال","الشحن وطرق الدفع والبطاقات والكوبونات"],["users","المستخدمون","الحسابات والأرصدة والحظر"],["marketing","التسويق","السلايدر والإعلانات والإشعارات"],["system","النظام","إعدادات المتجر والسجلات"]].map(([id,t,p])=>`<button class="card admin-tile" data-group="${id}"><h3>${t}</h3><p>${p}</p></button>`).join("")}</div>`;$$("[data-group]").forEach(b=>b.onclick=()=>{S.adminGroup=b.dataset.group;S.adminPage={sales:"orders",catalog:"products",finance:"deposits",users:"users",marketing:"slides",system:"settings"}[S.adminGroup];S.page=1;S.query="";S.filter="";admin()});return}const pages={sales:[["orders","الطلبات"],["cancel_requests","طلبات الإلغاء"]],catalog:[["products","المنتجات"],["categories","التصنيفات"],["inventory","المخزون"]],finance:[["deposits","طلبات الشحن"],["payment_methods","طرق الدفع"],["cards","بطاقات الشحن"],["coupons","الكوبونات"]],users:[["users","المستخدمون"]],marketing:[["slides","السلايدر"],["announcements","الإعلانات"],["notifications","الإشعارات"]],system:[["settings","الإعدادات"],["logs","سجل المدير"]]}[S.adminGroup];app.innerHTML=`${section("لوحة الإدارة",S.adminGroup,`<button id="backAdmin" class="btn soft">الرئيسية</button>`)}<div class="tabs">${pages.map(([id,n])=>`<button class="tab ${S.adminPage===id?"active":""}" data-admin-page="${id}">${n}</button>`).join("")}</div><div id="adminContent"></div>`;$("#backAdmin").onclick=()=>{S.adminGroup="dashboard";admin()};$$("[data-admin-page]").forEach(b=>b.onclick=()=>{S.adminPage=b.dataset.adminPage;S.page=1;S.query="";S.filter="";renderAdminPage()});renderAdminPage()}
function renderAdminPage(){({orders:adminOrders,cancel_requests:adminCancelRequests,products:adminProducts,categories:adminCategories,inventory:adminInventory,deposits:adminDeposits,payment_methods:adminPaymentMethods,cards:adminCards,coupons:adminCoupons,users:adminUsers,slides:adminSlides,announcements:adminAnnouncements,notifications:adminNotifications,settings:adminSettings,logs:adminLogs}[S.adminPage]||adminOrders)()}
async function listQuery(table,select="*",filterFn=null){let q=supabase.from(table).select(select,{count:"exact"}).order("created_at",{ascending:false});if(filterFn)q=filterFn(q);const from=(S.page-1)*CONFIG.PAGE_SIZE,to=from+CONFIG.PAGE_SIZE-1;return await q.range(from,to)}
function bindAdminSearch(render,filterOptions=[]){const s=$("#adminSearch"),f=$("#adminFilter");if(f&&filterOptions.length)f.innerHTML=`<option value="">الكل</option>${filterOptions.map(([v,n])=>`<option value="${v}" ${S.filter===v?"selected":""}>${n}</option>`).join("")}`;if(s)s.oninput=debounce(()=>{S.query=s.value.trim();S.page=1;render()});if(f)f.onchange=()=>{S.filter=f.value;S.page=1;render()};$("#clearFilters").onclick=()=>{S.query="";S.filter="";S.page=1;render()}}
async function adminOrders(){const{data,count}=await listQuery("orders","*,product:products(name,delivery_type),profile:profiles(full_name,phone)",q=>{if(S.filter)q=q.eq("status",S.filter);if(S.query)q=q.or(`order_number.ilike.%${S.query}%`);return q});const r=data||[];$("#adminContent").innerHTML=`${adminHeader("الطلبات","تنفيذ وتسليم واسترداد",`<button id="exportOrders" class="btn soft">تصدير CSV</button>`)}<div class="list">${r.map(o=>`<div class="card item"><div class="item-main"><h3>${esc(o.product?.name||"-")}</h3><p>${esc(o.profile?.full_name||"-")} • ${esc(o.order_number)} • ${money(o.total)}</p></div><div class="item-actions">${badge(o.status)}<button class="small" data-order-manage="${o.id}">إدارة</button></div></div>`).join("")||empty("لا توجد طلبات")}</div>${pager(S.page,count||0,CONFIG.PAGE_SIZE)}`;bindAdminSearch(adminOrders,[["processing","قيد التنفيذ"],["delivered","تم التسليم"],["cancelled","ملغي"],["refunded","مسترد"]]);bindPager(adminOrders);$("#exportOrders").onclick=()=>exportCsv("orders","orders.csv");$$("[data-order-manage]").forEach(b=>b.onclick=()=>manageOrder(r.find(x=>x.id===b.dataset.orderManage)))}
function manageOrder(o){openModal(`<div class="sheet-head"><div><h2>${esc(o.order_number)}</h2><p>${esc(o.profile?.full_name||"-")} • ${esc(o.profile?.phone||"-")}</p></div><button data-close>×</button></div><div class="note">المنتج: ${esc(o.product?.name||"-")}<br>القيمة: ${money(o.total)}<br>الحالة: ${badge(o.status)}</div><form id="orderAdminForm" style="margin-top:14px"><label>بيانات التسليم<textarea id="delivery">${esc(o.delivery_data||"")}</textarea></label><label>الإجراء<select id="orderStatus"><option value="processing">قيد التنفيذ</option><option value="delivered">تم التسليم</option><option value="cancelled">إلغاء وإعادة الرصيد</option><option value="refunded">استرداد الرصيد</option></select></label><label>سبب العملية<textarea id="orderReason"></textarea></label><button class="btn primary block">حفظ</button></form>`);$("#orderAdminForm").onsubmit=async e=>{e.preventDefault();const{error}=await supabase.rpc("admin_process_order",{p_order_id:o.id,p_status:$("#orderStatus").value,p_delivery_data:$("#delivery").value||null,p_reason:$("#orderReason").value||null});if(error)return toast(error.message,"error");toast("تم تحديث الطلب");closeModal();adminOrders()}}
async function adminCancelRequests(){const{data,count}=await listQuery("order_cancel_requests","*,order:orders(order_number,total,status),profile:profiles(full_name)",q=>{if(S.filter)q=q.eq("status",S.filter);return q});const r=data||[];$("#adminContent").innerHTML=`${adminHeader("طلبات الإلغاء","مراجعة طلبات العملاء")}<div class="list">${r.map(x=>`<div class="card item"><div class="item-main"><h3>${esc(x.order?.order_number||"-")}</h3><p>${esc(x.profile?.full_name||"-")} • ${esc(x.reason)}</p></div><div class="item-actions">${badge(x.status)}${x.status==="pending"?`<button class="success" data-cancel-approve="${x.id}">قبول</button><button class="danger" data-cancel-reject="${x.id}">رفض</button>`:""}</div></div>`).join("")||empty("لا توجد طلبات")}</div>${pager(S.page,count||0,CONFIG.PAGE_SIZE)}`;bindAdminSearch(adminCancelRequests,[["pending","معلق"],["approved","مقبول"],["rejected","مرفوض"]]);bindPager(adminCancelRequests);$$("[data-cancel-approve]").forEach(b=>b.onclick=()=>reviewCancel(b.dataset.cancelApprove,true));$$("[data-cancel-reject]").forEach(b=>b.onclick=()=>reviewCancel(b.dataset.cancelReject,false))}
async function reviewCancel(id,approve){const reason=approve?"قبول طلب الإلغاء":prompt("سبب الرفض:");if(!approve&&!reason)return;const{error}=await supabase.rpc("admin_review_cancel_request",{p_request_id:id,p_approve:approve,p_reason:reason});if(error)return toast(error.message,"error");toast("تمت معالجة الطلب");adminCancelRequests()}
async function adminProducts(){let q=supabase.from("products_with_stock").select("*",{count:"exact"}).order("created_at",{ascending:false});if(S.query)q=q.ilike("name",`%${S.query}%`);if(S.filter)q=q.eq("availability_status",S.filter);const from=(S.page-1)*CONFIG.PAGE_SIZE,{data,count}=await q.range(from,from+CONFIG.PAGE_SIZE-1),r=data||[];$("#adminContent").innerHTML=`${adminHeader("المنتجات","إضافة وتعديل وتعطيل",`<button id="addProduct" class="btn primary">إضافة منتج</button>`)}<div class="list">${r.map(p=>`<div class="card item"><div class="item-main"><h3>${esc(p.name)}</h3><p>${money(p.price)} • المخزون ${p.stock_count??"-"}</p></div><div class="item-actions">${badge(p.availability_status)}<button class="small" data-product-edit="${p.id}">تعديل</button><button class="danger" data-product-delete="${p.id}">حذف</button></div></div>`).join("")||empty("لا توجد منتجات")}</div>${pager(S.page,count||0,CONFIG.PAGE_SIZE)}`;bindAdminSearch(adminProducts,[["available","متاح"],["sold_out","نفد المخزون"]]);bindPager(adminProducts);$("#addProduct").onclick=()=>productForm();$$("[data-product-edit]").forEach(b=>b.onclick=async()=>{const{data}=await supabase.from("products").select("*").eq("id",b.dataset.productEdit).single();productForm(data)});$$("[data-product-delete]").forEach(b=>b.onclick=()=>deleteRow("products",b.dataset.productDelete,"المنتج",adminProducts))}
async function productForm(p=null){const{data:c}=await supabase.from("categories").select("*").order("name");openModal(`<div class="sheet-head"><h2>${p?"تعديل":"إضافة"} منتج</h2><button data-close>×</button></div><form id="productForm"><label>الاسم<input id="pn" value="${esc(p?.name||"")}" required></label><label>السعر<input id="pp" type="number" min="0" step=".01" value="${p?.price||0}" required></label><label>التصنيف<select id="pc"><option value="">بدون</option>${(c||[]).map(x=>`<option value="${x.id}" ${p?.category_id===x.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select></label><label>نوع التسليم<select id="pd"><option value="automatic">تلقائي</option><option value="manual" ${p?.delivery_type==="manual"?"selected":""}>يدوي</option></select></label><label>حالة المنتج اليدوي<select id="pm"><option value="available">متاح</option><option value="paused" ${p?.manual_availability==="paused"?"selected":""}>موقوف</option><option value="sold_out" ${p?.manual_availability==="sold_out"?"selected":""}>نفد</option></select></label><label>رابط الصورة<input id="pi" type="url" value="${esc(p?.image_url||"")}"></label><label>الوصف<textarea id="pdesc">${esc(p?.description||"")}</textarea></label><label><input id="pa" type="checkbox" ${p?.is_active!==false?"checked":""}> مفعّل</label><button class="btn primary block">حفظ</button></form>`);$("#productForm").onsubmit=async e=>{e.preventDefault();const payload={name:$("#pn").value.trim(),price:+$("#pp").value,category_id:$("#pc").value||null,delivery_type:$("#pd").value,manual_availability:$("#pm").value,image_url:$("#pi").value||null,description:$("#pdesc").value,is_active:$("#pa").checked};const query=p?supabase.from("products").update(payload).eq("id",p.id):supabase.from("products").insert(payload);const{error}=await query;if(error)return toast(error.message,"error");toast("تم الحفظ");closeModal();adminProducts()}}
async function adminCategories(){const{data,count}=await listQuery("categories","*",q=>{if(S.query)q=q.ilike("name",`%${S.query}%`);if(S.filter)q=q.eq("is_active",S.filter==="active");return q});const r=data||[];$("#adminContent").innerHTML=`${adminHeader("التصنيفات","إضافة وتعديل وترتيب",`<button id="addCategory" class="btn primary">إضافة تصنيف</button>`)}<div class="list">${r.map(c=>`<div class="card item"><div class="item-main"><h3>${esc(c.name)}</h3><p>الترتيب ${c.sort_order}</p></div><div class="item-actions">${c.is_active?badge("active"):badge("blocked")}<button class="small" data-cat-edit="${c.id}">تعديل</button><button class="danger" data-cat-delete="${c.id}">حذف</button></div></div>`).join("")||empty("لا توجد تصنيفات")}</div>${pager(S.page,count||0,CONFIG.PAGE_SIZE)}`;bindAdminSearch(adminCategories,[["active","مفعّل"],["inactive","موقوف"]]);bindPager(adminCategories);$("#addCategory").onclick=()=>categoryForm();$$("[data-cat-edit]").forEach(b=>b.onclick=async()=>{const{data}=await supabase.from("categories").select("*").eq("id",b.dataset.catEdit).single();categoryForm(data)});$$("[data-cat-delete]").forEach(b=>b.onclick=()=>deleteRow("categories",b.dataset.catDelete,"التصنيف",adminCategories))}
